// Category C: no headless rating exists, so the behaviour is React Aria's RadioGroup, one radio per
// star (the shape MUI's Rating takes): arrow keys move the value, each star is announced by its own
// name, and the group is one tab stop. The look is ours. A read-only rating is not a control at all,
// so it renders a picture named by its value instead, which is how it can show a fraction. Each glyph
// sits in a span that carries its class: the icon paints `color: currentColor` inline, so a colour set
// on the svg itself would lose.
import { Label, Radio, RadioGroup } from "react-aria-components";
import type { RadioGroupProps } from "react-aria-components";
import { useId, useState, type CSSProperties, type Ref } from "react";
import { Star } from "./icons";
import "./Rating.css";

type RatingSize = "small" | "medium" | "large";
type RatingVariant = "stars" | "single";

export interface RatingBaseProps
  extends Omit<RadioGroupProps, "className" | "children" | "value" | "defaultValue" | "onChange" | "orientation"> {
  /**
   * `stars` draws one star per point of `max`. `single` draws one filled star and the score beside
   * it, the compact readout a list row carries; it is read-only and always shows the value.
   *
   * @default "stars"
   */
  variant?: RatingVariant;
  /**
   * Size axis: the stars and the label.
   *
   * @default "medium"
   */
  size?: RatingSize;
  /** The rating, from 0 to `max`. A read-only rating may hold a fraction (4.5); an input holds whole stars. */
  value?: number;
  /** The rating it starts at, uncontrolled. */
  defaultValue?: number;
  /**
   * How many stars.
   *
   * @default 5
   */
  max?: number;
  /** Called with the chosen number of stars. */
  onChange?: (value: number) => void;
  /** Visible label above the stars, or before them with `labelPlacement="start"`. */
  label?: string;
  /** Show the score as text beside the stars. The stars then restate the text, so they are drawn as
   *  decoration (the vivid rating hue on the edge as well as the fill) and the score is read once.
   *  Read-only only. */
  showValue?: boolean;
  /**
   * Where the label sits: above the stars, or before them on one line (a row of category ratings).
   *
   * @default "top"
   */
  labelPlacement?: "top" | "start";
}

/** A rating needs a name: a visible `label`, or `aria-label` / `aria-labelledby` (WCAG 4.1.2). The
 *  one exception is a read-only rating beside text that already states the score (a summary's "4.5
 *  out of 5"): `aria-hidden` makes its stars decoration, so the score is not read twice. */
export type RatingProps = RatingBaseProps &
  (
    | { label: string }
    | { isReadOnly: true; "aria-hidden": true }
    | { "aria-label": string }
    | { "aria-labelledby": string }
  ) & {
    /** Additional class. sd-rating is always retained. */
    className?: string;
    /** Forwarded to the root DOM node. */
    ref?: Ref<HTMLDivElement>;
  };

const clamp = (n: number, max: number) => Math.min(Math.max(n, 0), max);

export function Rating({
  variant = "stars",
  size = "medium",
  value,
  defaultValue,
  max = 5,
  onChange,
  label,
  showValue = false,
  labelPlacement = "top",
  isReadOnly,
  className,
  ref,
  ...props
}: RatingProps) {
  const [own, setOwn] = useState(defaultValue ?? 0);
  const [hovered, setHovered] = useState<number | null>(null);
  const scoreId = useId();
  const current = clamp(value ?? own, max);
  const classes = className ? `sd-rating ${className}` : "sd-rating";
  const stars = Array.from({ length: max }, (_, i) => i + 1);

  if (isReadOnly || variant === "single") {
    // Nothing to operate, so one picture with one name: its field name, then "4.5 out of 5". The
    // score is a separate part of the name, so a consumer's `aria-label` or `aria-labelledby` names
    // the field without hiding the value. Each star's share of the value is how much of its filled
    // glyph shows.
    const { id, style, dir, "aria-label": ariaLabel, "aria-labelledby": labelledBy, "aria-describedby": describedBy, isDisabled } = props;
    const hidden = "aria-hidden" in props && !!props["aria-hidden"];
    const score = `${current} out of ${max}`;
    const single = variant === "single";
    const valueShown = single || showValue;
    return (
      <div
        ref={ref}
        id={id}
        dir={dir}
        style={typeof style === "object" ? style : undefined}
        data-size={size}
        data-variant={variant}
        data-label-placement={labelPlacement}
        data-read-only
        // The score is stated in text (beside the stars, or by the consumer next to a hidden rating),
        // so the stars carry no information of their own and their edge takes the decorative hue too.
        data-decorative={valueShown || hidden || undefined}
        data-disabled={isDisabled || undefined}
        aria-hidden={hidden || undefined}
        className={classes}
      >
        {label && (
          <span aria-hidden="true" className={`sd-rating__label sd-type-label-${size}`}>
            {label}
          </span>
        )}
        <span
          className="sd-rating__stars"
          role={hidden ? undefined : "img"}
          aria-label={hidden || labelledBy ? undefined : `${ariaLabel ?? label ? `${ariaLabel ?? label}: ` : ""}${score}`}
          aria-labelledby={!hidden && labelledBy ? `${labelledBy} ${scoreId}` : undefined}
          aria-describedby={hidden ? undefined : describedBy}
        >
          {labelledBy && (
            <span id={scoreId} hidden>
              {score}
            </span>
          )}
          {(single ? [1] : stars).map((n) => (
            <span
              key={n}
              data-read-only
              className="sd-rating__star"
              // A single star is the mark of "a rating", not a share of the score, so it is full.
              style={{ "--sd-rating-star-share": `${single ? 100 : clamp(current - n + 1, 1) * 100}%` } as CSSProperties}
            >
              <span aria-hidden="true" className="sd-rating__empty"><Star size="1em" /></span>
              <span aria-hidden="true" className="sd-rating__filled"><Star size="1em" filled /></span>
            </span>
          ))}
        </span>
        {valueShown && (
          // Visible, and hidden from assistive tech: the stars' own name already reads the score. The full
          // readout states the score in the emphasized weight; the single readout is a list row's muted
          // aside to its star, so it keeps the role's own weight.
          <span aria-hidden="true" data-variant={variant} className={`sd-rating__value sd-type-body-${size}${single ? "" : "-emphasized"}`}>
            {current.toFixed(1)}
          </span>
        )}
      </div>
    );
  }

  // The preview shows what a press would choose; it gives way to the value the moment the value
  // changes (a key press under a resting pointer) and never shows on a disabled rating.
  const shown = (!props.isDisabled && hovered) || Math.round(current);
  return (
    <RadioGroup
      {...props}
      ref={ref}
      orientation="horizontal"
      data-size={size}
      value={current ? String(Math.round(current)) : null}
      onChange={(v) => {
        const n = Number(v);
        setHovered(null);
        if (value === undefined) setOwn(n);
        onChange?.(n);
      }}
      className={classes}
    >
      {label && <Label className={`sd-rating__label sd-type-label-${size}`}>{label}</Label>}
      <div className="sd-rating__stars" onPointerLeave={() => setHovered(null)}>
        {stars.map((n) => (
          <Radio
            key={n}
            value={String(n)}
            aria-label={`${n} ${n === 1 ? "star" : "stars"}`}
            onHoverStart={() => setHovered(n)}
            onHoverEnd={() => setHovered((h) => (h === n ? null : h))}
            data-on={n <= shown || undefined}
            className="sd-rating__star"
          >
            <span aria-hidden="true" className="sd-rating__empty"><Star size="1em" /></span>
            <span aria-hidden="true" className="sd-rating__filled"><Star size="1em" filled /></span>
          </Radio>
        ))}
      </div>
    </RadioGroup>
  );
}

/* Rating.css — .sd-rating (+ __label · __stars · __star · __empty · __filled)
   Each star is two glyphs stacked: the outline, and the filled star clipped to its share of the
   value. One relay carries the share for both modes: 0 or 100% from a radio's state, or a fraction
   a read-only rating sets inline. A filled star paints its inside and its edge apart: the inside is
   always the vivid rating hue, so every star reads yellow, and the edge carries the 3:1 the star owes
   WCAG 1.4.11 where it alone states the score (ADR-0052 Amendment 1). */
.sd-rating {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--sd-rating-gap);
  --sd-rating-star-size-current: var(--sd-rating-star-size-medium);
  --sd-rating-star-stroke-filled-current: var(--sd-rating-star-stroke-filled);
}
.sd-rating[data-size="small"] {
  --sd-rating-star-size-current: var(--sd-rating-star-size-small);
}
.sd-rating[data-size="large"] {
  --sd-rating-star-size-current: var(--sd-rating-star-size-large);
}
/* A label before the stars, and the single readout: one line, centred on the stars. */
.sd-rating[data-label-placement="start"],
.sd-rating[data-variant="single"] {
  flex-direction: row;
  align-items: center;
}
/* The single star and its readout are one glyph and its value, the pair Button's icon and label are:
   the glyph-rhythm gap plus the value's own text inset, so the ink sits one action-row rung from
   the star rather than the whole gap plus the inset. */
.sd-rating[data-variant="single"] {
  gap: var(--sd-rating-stars-gap);
}
.sd-rating[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-rating__label {
  padding-inline: var(--sd-rating-text-padding-inline);
  color: var(--sd-rating-label-foreground);
}

.sd-rating__stars {
  display: inline-flex;
  gap: var(--sd-rating-stars-gap);
}

.sd-rating__star {
  /* How much of the filled glyph shows: none at rest. */
  --sd-rating-star-share: 0%;
  position: relative;
  display: inline-flex;
  font-size: var(--sd-rating-star-size-current);
  color: var(--sd-rating-star-foreground-empty);
  border-radius: var(--sd-rating-star-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  outline: none;
}
.sd-rating__star[data-on] {
  --sd-rating-star-share: 100%;
}
.sd-rating__star[data-disabled] {
  cursor: not-allowed;
}
.sd-rating__star[data-read-only] {
  cursor: inherit;
}
.sd-rating__star[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* Neither glyph takes the pointer. The hover preview fills a star under the pointer, which would
   swap the element hit between press and release, and a click needs both on one element; the label
   around them is the target either way. */
.sd-rating__empty {
  display: flex;
  pointer-events: none;
}
.sd-rating__filled {
  position: absolute;
  inset: 0;
  display: flex;
  pointer-events: none;
  color: var(--sd-rating-star-stroke-filled-current);
  clip-path: inset(0 calc(100% - var(--sd-rating-star-share)) 0 0);
}
/* The edge rides currentColor (the icon's stroke attribute); a CSS fill outranks the fill attribute
   the icon writes, so the inside takes its own colour. */
.sd-rating__filled .sd-icon {
  fill: var(--sd-rating-star-fill-filled);
}
/* A rating fills from the reading start, so in a right-to-left page it fills from the right. */
.sd-rating__filled:dir(rtl) {
  clip-path: inset(0 0 0 calc(100% - var(--sd-rating-star-share)));
}

/* Decorative stars: the score is stated in text, so the edge owes no contrast and drops its 3:1 step
   for the fill's vivid hue, one colour (sys-tokens.md, icon.rating.decorative). Set on the root,
   read by each glyph. */
.sd-rating[data-decorative] {
  --sd-rating-star-stroke-filled-current: var(--sd-rating-star-stroke-filled-decorative);
}

.sd-rating__value {
  padding-inline-end: var(--sd-rating-text-padding-inline);
  color: var(--sd-rating-value-foreground);
}
.sd-rating__value[data-variant="single"] {
  color: var(--sd-rating-value-foreground-single);
}
